{"implementation": "def solve(case):
    segments = list(case.get('segments', []))
    budget = int(case.get('budget', 0))
    n = len(segments)

    if n == 0:
        return {'allocations': [], 'by_name': {}, 'total': 0}

    minimums = [int(s.get('minimum', 0)) for s in segments]
    capacities = [int(s.get('capacity', minimums[i])) for i, s in enumerate(segments)]
    weights = [int(s.get('importance', 0)) for s in segments]

    allocations = [0] * n
    remaining = budget

    for i in range(n):
        take = min(minimums[i], capacities[i])
        allocations[i] = take
        remaining -= take

    if remaining < 0:
        allocations = [0] * n
        remaining = budget
        order = sorted(range(n), key=lambda i: (-weights[i], i))
        for i in order:
            if remaining <= 0:
                break
            take = min(capacities[i], remaining)
            allocations[i] = take
            remaining -= take
    elif remaining > 0:
        active = [i for i in range(n) if capacities[i] > allocations[i]]
        while remaining > 0 and active:
            total_weight = sum(max(0, weights[i]) for i in active)
            if total_weight <= 0:
                order = sorted(active)
                changed = False
                for i in order:
                    if remaining <= 0:
                        break
                    if allocations[i] < capacities[i]:
                        allocations[i] += 1
                        remaining -= 1
                        changed = True
                if not changed:
                    break
                active = [i for i in active if allocations[i] < capacities[i]]
                continue

            quotas = []
            base_adds = [0] * n
            used = 0
            for i in active:
                extra_cap = capacities[i] - allocations[i]
                exact_num = remaining * max(0, weights[i])
                base = exact_num // total_weight
                if base > extra_cap:
                    base = extra_cap
                base_adds[i] = base
                used += base
                quotas.append((exact_num / total_weight - (exact_num // total_weight), -weights[i], i))

            if used == 0:
                quotas.sort(key=lambda x: (-x[0], x[1], x[2]))
                changed = False
                for _, _, i in quotas:
                    if remaining <= 0:
                        break
                    if allocations[i] < capacities[i]:
                        allocations[i] += 1
                        remaining -= 1
                        changed = True
                if not changed:
                    break
            else:
                for i, add in enumerate(base_adds):
                    if add:
                        allocations[i] += add
                        remaining -= add

            active = [i for i in range(n) if allocations[i] < capacities[i]]

    by_name = {segments[i].get('name'): allocations[i] for i in range(n)}
    return {'allocations': allocations, 'by_name': by_name, 'total': sum(allocations)}
"}
